const home::Section* Editor::activeHomeFolder()const{if(homeSection_!=3)return nullptr;auto it=std::find_if(homeSections_.begin(),homeSections_.end(),[this](const auto& s){return s.id==homeSectionId_&&s.kind=="folder";});return it==homeSections_.end()?nullptr:&*it;}
void Editor::loadHomeSections(){homeFormats_=63;const auto dir=recentSettingsOverride_.empty()?homeRecentPath().parent_path():recentSettingsOverride_;try{homeSections_=home::decode(gallery::read(dir/"moonsprite.home-sections.v1"));}catch(...){homeSections_=home::normalize({});}try{const auto value=gallery::read(dir/"moonsprite.home-file-display-formats.v1");if(value.size()==6&&value.find_first_not_of("01")==std::string::npos){homeFormats_=0;for(int i=0;i<6;++i)if(value[i]=='1')homeFormats_|=1u<<i;}}catch(...){}std::string active;try{active=gallery::read(dir/"moonsprite.home-section.v1");}catch(...){}auto it=std::find_if(homeSections_.begin(),homeSections_.end(),[&](const auto& s){return s.id==active;});homeSectionId_=it==homeSections_.end()?homeSections_.front().id:it->id;const auto& s=it==homeSections_.end()?homeSections_.front():*it;homeSection_=s.kind=="recent"?0:s.kind=="gallery"?1:s.kind=="recovery"?2:3;}
void Editor::saveHomeSections(){if(smoke_&&recentSettingsOverride_.empty())return;try{const auto dir=recentSettingsOverride_.empty()?homeRecentPath().parent_path():recentSettingsOverride_;std::filesystem::create_directories(dir);const auto value=home::encode(homeSections_);writeExportBytesAtomic(dir/"moonsprite.home-sections.v1",{value.begin(),value.end()});writeExportBytesAtomic(dir/"moonsprite.home-section.v1",{homeSectionId_.begin(),homeSectionId_.end()});std::string formats;for(int i=0;i<6;++i)formats+=(homeFormats_&(1u<<i))?'1':'0';writeExportBytesAtomic(dir/"moonsprite.home-file-display-formats.v1",{formats.begin(),formats.end()});}catch(const std::exception& e){status_=U"栏目设置写入失败："+unicodeText(e.what());}}
void Editor::selectHomeSection(const std::string& id){auto it=std::find_if(homeSections_.begin(),homeSections_.end(),[&](const auto& s){return s.id==id;});if(it==homeSections_.end())return;homeSectionId_=it->id;homeSection_=it->kind=="recent"?0:it->kind=="gallery"?1:it->kind=="recovery"?2:3;folderQueue_.cancel();folderLoading_=false;saveHomeSections();loadHomeSection();refresh();}
void Editor::addHomeFolder(const std::string& directory){auto f=home::folder(directory);if(f.directory.empty())return;auto it=std::find_if(homeSections_.begin(),homeSections_.end(),[&](const auto& s){return s.kind=="folder"&&home::key(s.directory)==home::key(f.directory);});if(it!=homeSections_.end()){const auto id=it->id;selectHomeSection(id);return;}homeSections_.push_back(f);selectHomeSection(f.id);}
void Editor::removeHomeFolder(const std::string& id){auto it=std::find_if(homeSections_.begin(),homeSections_.end(),[&](const auto& s){return s.id==id&&s.kind=="folder";});if(it==homeSections_.end())return;const auto index=std::size_t(it-homeSections_.begin());const bool selected=homeSectionId_==id;homeSections_.erase(it);if(selected)selectHomeSection(homeSections_[std::min(index,homeSections_.size()-1)].id);else{saveHomeSections();refresh();}}
void Editor::loadHomeFolder(){folderProjects_.clear();folderError_.clear();folderLoading_=false;auto f=activeHomeFolder();if(!f)return;const auto directory=std::filesystem::u8path(f->directory);const auto pins=galleryPins_;folderLoading_=true;folderGeneration_=folderQueue_.request([directory,pins](const std::function<bool()>& canceled){if(!std::filesystem::is_directory(directory))throw std::runtime_error("所选文件夹不存在或无法访问。");return gallery::list(directory,pins,canceled,true);});}
void Editor::homeFolderTick(){auto result=folderQueue_.take();if(!result||result->generation!=folderGeneration_)return;folderLoading_=false;folderProjects_=std::move(result->projects);folderError_=std::move(result->error);if(homeSection_==3){if(!folderError_.empty())status_=U"文件夹读取失败："+unicodeText(folderError_);if(homeOpen_)refresh();}}
void Editor::showHomeOverflow(){PixelMenu menu(skin_);for(std::size_t i=0;i<homeSections_.size();++i){if(i<homeTabs_.size()&&homeTabs_[i]->isVisible())continue;const auto& s=homeSections_[i];auto row=new PixelMenuItem(font_,skin_,HomeSectionRows::name(s));row->iconSkin=&toolIcons_;row->icon=s.kind=="folder"?"folderOpen":s.kind=="recovery"?"refresh":"image";row->checked=[this,id=s.id]{return homeSectionId_==id;};row->Click.connect([this,id=s.id]{selectHomeSection(id);});menu.addChild(row);}menu.showPopup({homeMore_->bounds().x,homeMore_->bounds().y2()},display());requestFocus();}
void Editor::showHomeSectionManager(int verify){if(pending_!=Pending::None)return;bool orderPending=false;HomeSectionDialog* current=nullptr;auto sync=[&]{if(current)current->setValues(homeSections_,homeSectionId_,homeFormats_);};HomeSectionDialog popup(font_,skin_,toolIcons_,[&]{BROWSEINFOW options{};options.hwndOwner=GetActiveWindow();options.lpszTitle=L"选择文件夹";options.ulFlags=BIF_RETURNONLYFSDIRS|BIF_NEWDIALOGSTYLE;const auto initial=activeHomeFolder()?std::filesystem::u8path(activeHomeFolder()->directory).wstring():std::wstring{};options.lParam=reinterpret_cast<LPARAM>(initial.c_str());options.lpfn=[](HWND window,UINT message,LPARAM,LPARAM data)->int{if(message==BFFM_INITIALIZED&&data)SendMessageW(window,BFFM_SETSELECTIONW,TRUE,data);return 0;};const auto chosen=SHBrowseForFolderW(&options);if(!chosen)return;wchar_t path[32768]{};const bool ok=SHGetPathFromIDListEx(chosen,path,32768,GPFIDL_DEFAULT);CoTaskMemFree(chosen);if(ok)addHomeFolder(std::filesystem::path(path).u8string());else{status_=U"无法读取所选文件夹";invalidate();}sync();});current=&popup;popup.rows().select=[&](const std::string& id){selectHomeSection(id);sync();};popup.rows().remove=[&](const std::string& id){removeHomeFolder(id);sync();};popup.rows().reorder=[&](const std::string& source,const std::string& target,bool after){auto next=home::reorder(homeSections_,source,target,after);if(next.size()==homeSections_.size()&&std::equal(next.begin(),next.end(),homeSections_.begin(),[](const auto& a,const auto& b){return a.id==b.id;}))return;homeSections_=std::move(next);orderPending=true;refresh();sync();};popup.formatChanged=[&](int i,bool checked){if(checked)homeFormats_|=1u<<i;else homeFormats_&=~(1u<<i);saveHomeSections();refresh();sync();};ui::Timer saveTimer(180,&popup);saveTimer.Tick.connect([&]{if(orderPending){orderPending=false;saveHomeSections();}});saveTimer.start();sync();popup.setDisplay(display(),false);popup.setBounds({bounds().center().x-190*uiScale,bounds().center().y-160*uiScale,380*uiScale,320*uiScale});int phase=0;ui::Timer timer(80,&popup);if(verify){timer.Tick.connect([&]{timer.stop();if(phase++==0){popup.rows().smokeSelect(0);popup.smokeFormat(1);if(homeSections_.size()>3){popup.rows().smokeReorder(homeSections_.size()-1,0,false);popup.rows().smokeSelect(0);}timer.start();return;}writeSmokeFrame(popup.display()->nativeSurface().get(),recentSettingsOverride_/"home-sections-dialog.bmp");popup.smokeClose();});timer.start();}popup.openWindowInForeground();saveTimer.stop();if(orderPending)saveHomeSections();requestFocus();refresh();}
void Editor::smokeHomeSections(){smoke_=true;pending_=Pending::None;documentOpen_=false;homeOpen_=true;homeSection_=0;homeSectionId_="recent";homeSections_=home::normalize({});homeFormats_=63;recentSettingsOverride_=assets_.parent_path()/("home-sections-ui-test-owned-"+std::to_string(recent::now()));std::filesystem::create_directories(recentSettingsOverride_);std::ofstream(recentSettingsOverride_/"test-owned.marker")<<"Home sections owned test";auto check=[](bool v,const char* why){if(!v)throw std::runtime_error(why);};const auto dir=recentSettingsOverride_/L"作品文件夹";std::filesystem::create_directories(dir);Document d(3,2);project::saveDocumentAtomic(d,dir/"art.moonsprite");auto png=encodeRgbaImagePng(1,1,{0xff112233});writeExportBytesAtomic(dir/"image.PNG",png.png);std::ofstream(dir/"ignored.txt")<<"ignored";addHomeFolder(dir.u8string());auto wait=[&]{const auto deadline=GetTickCount64()+8000;while(folderLoading_&&GetTickCount64()<deadline){homeFolderTick();Sleep(5);}check(!folderLoading_&&folderError_.empty(),"Folder background completion");refresh();};wait();check(homeSections_.size()==4&&homeSection_==3&&recentPane_->count()==2,"Folder entry lists project and image only");const auto folderId=homeSectionId_;std::filesystem::path opened;auto launcher=projectFolderLauncher_;projectFolderLauncher_=[&](const auto& p){opened=p;};galleryFolder_->Click();projectFolderLauncher_=launcher;check(opened==dir,"Folder tool opens selected directory");recentPane_->remove((dir/"art.moonsprite").u8string());check(std::filesystem::exists(dir/"art.moonsprite"),"Folder cards cannot invoke gallery deletion");homeFormats_=0;refresh();check(recentPane_->count()==0&&homeFilesHidden_,"Empty format selection hides all files");homeFormats_=63;refresh();addHomeFolder(dir.u8string()+"\\");wait();check(homeSections_.size()==4&&homeSectionId_==folderId,"Duplicate folder selects existing entry");homeFormats_=1;saveHomeSections();refresh();check(recentPane_->count()==1&&homeFilesHidden_,"Project-only filter hides image");loadHomeSections();check(homeSectionId_==folderId&&homeFormats_==1,"Folder selection and formats persist");recentPane_->smokePin(0);check(!galleryPins_.empty(),"Folder pin shares independent gallery pins");recentPane_->smokeOpen(0);check(currentDocument().width()==3&&sameProjectPath(currentPath(),dir/"art.moonsprite"),"Folder actual card opens project");showHome(true);wait();check(std::any_of(homeTabs_.begin(),homeTabs_.end(),[&](const auto* b){return b->isVisible()&&b->active;}),"Active folder remains visible among overflow tabs");homeFormats_=63;selectHomeSection(folderId);wait();showHomeSectionManager(1);check(homeSection_==3&&homeSectionId_==folderId&&homeFormats_==61&&homeSections_.front().id==folderId,"Actual manager selection, drag callback and format checkbox");homeSections_=home::reorder(homeSections_,folderId,"recent",false);saveHomeSections();loadHomeSections();check(homeSections_.front().id==folderId,"Reorder persists");selectHomeSection(folderId);wait();HomeSectionDialog removeDialog(font_,skin_,toolIcons_,[]{});removeDialog.rows().remove=[this](const auto& id){removeHomeFolder(id);};removeDialog.setValues(homeSections_,homeSectionId_,homeFormats_);removeDialog.rows().smokeRemove(0);check(homeSections_.size()==3&&homeSection_==0&&std::filesystem::exists(dir/"art.moonsprite")&&std::filesystem::exists(dir/"image.PNG"),"Removing active folder only removes entry and selects next");addHomeFolder((recentSettingsOverride_/"missing").u8string());const auto deadline=GetTickCount64()+8000;while(folderLoading_&&GetTickCount64()<deadline){homeFolderTick();Sleep(5);}check(!folderError_.empty()&&recentPane_->count()==0,"Missing folder reports error");removeHomeFolder(homeSectionId_);homeFormats_=63;selectHomeSection("recent");}
